// My Neighbor Has a Podcast: ten-shot timeline (30 fps, 1530 frames = 51.0 s). Frame ranges follow SHOTLIST.md;
// sub-shot cuts and action cues are in absolute frames. Spoken-line placements live in src/voice.json
// (generated by audio/tools/align_voices.py from the actual takes) and are checked to stay disjoint.
import voice from "./voice.json";

export const FPS = 30;
export const TOTAL = 1530;

export type SetId = "porch" | "night" | "safe" | "woods";
export type Shot = { id: string; from: number; to: number; set: SetId };

export const SHOTS: Shot[] = [
  { id: "S01", from: 0, to: 210, set: "porch" },
  { id: "S02", from: 210, to: 366, set: "porch" },
  { id: "S03", from: 366, to: 450, set: "night" },
  { id: "S04", from: 450, to: 585, set: "night" },
  { id: "S05", from: 585, to: 735, set: "safe" },
  { id: "S06", from: 735, to: 900, set: "safe" },
  { id: "S07", from: 900, to: 1095, set: "woods" },
  { id: "S08", from: 1095, to: 1200, set: "woods" },
  { id: "S09", from: 1200, to: 1320, set: "woods" },
  { id: "S10", from: 1320, to: 1530, set: "woods" },
];

/** Locked picture cues (absolute frames). The bat contact and baby stand are owner-specified. */
export const CUE = {
  // S01
  glassRelease: 34, hostSits: 92, notesTap: [100, 108] as const, lensLook: 116,
  // S02
  doorOpen: 214, fisheyeCut: 322, swingStart: 330, impact: 345, // 345..365 black
  // S03
  monitorOn: 384, cribCut: 420,
  // S04
  micRaise: 478, babyGrab: 474, riseStart: 496, stand: 510, sitStart: 530, sitDown: 542,
  // S05
  monitorIn: 606, monitorRelease: 640, doorPushStart: 676, clunk: 722,
  // S06
  safeCrack: 742, safeOpen: 772, lookDown: 873, lookBack: 888,
  // S07
  roadCut: 1004,
  // S08
  shouldersDrop: 1112, sipStart: 1174, sipEnd: 1194,
  // S09/S10
  reachOut: 1214, bearEnter: 1234, footfalls: [1240, 1256, 1268] as const, bearSitStart: 1272, chairCreak: 1300,
  bearLean: 1446, breath: 1478, black: 1525,
};

export type Line = { id: string; who: "narrator" | "host"; in: number; out: number; text: string };
export const LINES: Line[] = (voice as { lines: Line[] }).lines;

/** host lip-sync envelope (frame-indexed mouth-open 0..1), from align_voices.py */
export const HOST_ENV: number[] = (voice as { hostEnv: number[] }).hostEnv;

export const shotAt = (frame: number) => SHOTS.find((s) => frame >= s.from && frame < s.to) ?? SHOTS[SHOTS.length - 1];

// sanity checks run at bundle time
SHOTS.forEach((s, i) => {
  if (i > 0 && SHOTS[i - 1].to !== s.from) throw new Error(`gap before ${s.id}`);
});
if (SHOTS[SHOTS.length - 1].to !== TOTAL) throw new Error("timeline must end at TOTAL");
